-- Fechamento de fretes: romaneios importados do Tático, km/valor por entrega, descontos e relatório para o financeiro.
-- (aplicada via execute_sql; RLS só o Bruno enquanto está em teste)
create table if not exists frete_freteiros (id serial primary key, apelido text not null unique, nome_tatico text not null default '', cod_transp text not null default '', favorecido text not null default '', agencia text not null default '', conta text not null default '', valor_km numeric not null default 3, ativo boolean not null default true, ordem int not null default 0, criado_em timestamptz not null default now());
create table if not exists frete_tat_rom (id serial primary key, mes text not null, romaneio text not null unique, cod_transp text not null default '', transportadora text not null default '', freteiro_id int references frete_freteiros(id) on delete set null, data date, itens jsonb not null default '[]', modo text not null default 'linhas', km numeric, valor_entregas numeric, valor_km numeric not null default 3, total_papel numeric, obs text not null default '', conferido boolean not null default false, atualizado_em timestamptz not null default now(), atualizado_por uuid);
create table if not exists frete_descontos (id serial primary key, mes text not null, freteiro_id int not null references frete_freteiros(id) on delete cascade, descricao text not null default '', parcela text not null default '', valor numeric not null, criado_em timestamptz not null default now());
create table if not exists frete_fechamento (mes text primary key, data_pagamento date, obs text not null default '', atualizado_em timestamptz not null default now());
-- RLS: policy *_bruno em cada tabela (auth.uid() = Bruno)
